// the trigger lookup THROWS if that trigger never executed (e.g. this workflow
// run via Manual Trigger alone) — confirmed via live E2E testing (this exact
// node crashed the workflow the first time it was run this way). try/catch
// makes "never executed" and "executed with zero items" behave the same.
let trigger = {};
try {
  const triggerItems = $('When Executed by Another Workflow').all();
  trigger = triggerItems.length ? triggerItems[0].json : {};
} catch (e) { trigger = {}; }
return [{ json: { runType: trigger.runType || 'LIVE' } }];

function isNumber(v) { return typeof v === 'number' && Number.isFinite(v); }
function round(v, d) { return isNumber(v) ? Math.round(v * Math.pow(10, d)) / Math.pow(10, d) : null; }
function pctChangeSafe(from, to) {
  if (!isNumber(from) || !isNumber(to) || from === 0) return null;
  return ((to - from) / from) * 100;
}

// Runs once for the WHOLE batch — one item per evaluable scanner_result
// arrives here from "Load Next Session Data". Must loop $input.all()
// explicitly (same bug pattern found and fixed across 04/05/06/07-10/11 via
// live E2E testing). itemMatching(i) pairs each row back to its scanner_result.

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  let original;
  try { original = $('Load Evaluable Scanner Results').itemMatching(i).json; } catch (e) { continue; }
  const row = items[i].json;

  if (!row || !isNumber(row.next_close)) {
    out.push({ json: { scannerResultId: original.scanner_result_id, _skip: true } });
    continue;
  }

  const returnOpenToClosePct = round(pctChangeSafe(row.next_open, row.next_close), 4);
  const returnPreviousCloseToClosePct = round(pctChangeSafe(row.previous_close, row.next_close), 4);
  const mfePct = isNumber(row.previous_close) && row.previous_close > 0
    ? round(((row.next_high - row.previous_close) / row.previous_close) * 100, 4) : null;
  const maePct = isNumber(row.previous_close) && row.previous_close > 0
    ? round(((row.next_low - row.previous_close) / row.previous_close) * 100, 4) : null;

  const target1Hit = isNumber(original.target1) ? row.next_high >= original.target1 : null;
  const target2Hit = isNumber(original.target2) ? row.next_high >= original.target2 : null;
  const target3Hit = isNumber(original.target3) ? row.next_high >= original.target3 : null;
  const stopHit = isNumber(original.invalidation_price) ? row.next_low <= original.invalidation_price : null;

  const success = target1Hit !== null
    ? (target1Hit === true && stopHit !== true)
    : (returnPreviousCloseToClosePct !== null ? returnPreviousCloseToClosePct > 0 : null);

  out.push({ json: {
    scannerResultId: original.scanner_result_id,
    nextTradingDate: row.next_trading_date,
    nextOpen: row.next_open, nextHigh: row.next_high, nextLow: row.next_low, nextClose: row.next_close,
    returnOpenToClosePct, returnPreviousCloseToClosePct, mfePct, maePct,
    target1Hit, target2Hit, target3Hit, stopHit, success,
    _skip: false,
  } });
}

return out;

const count = $input.first().json.evaluated_count;
return [{ json: {
  workflow: '14-egx-prediction-evaluation',
  finishedAt: new Date().toISOString(),
  totalEvaluatedRows: count,
} }];
